"""Mini router de respaldo (Director 2026-10-03): vive SOLO en Hugging Face (este Space), no depende de GitHub.

Dos opciones fijas de computo, encendidas solo por llamado y dormidas a los 5 min sin llamadas:
  t4 -> HF Job t4-small (16 GB GPU, $0.40/h)      l4 -> HF Job l4x1 (24 GB GPU, $0.80/h)
Cada procesador sirve un modelo con vLLM (API OpenAI). Tope de gasto por procesador (default $5): al llegarlo se apaga y
queda BLOQUEADO hasta aprobar (trigger POST /mini/approve, pensado para un boton en la UI). Selector de costo y tiempo:
POST /mini/config {gpu, model, cap_usd, max_minutes, idle_s}. Estado y gasto se guardan en el bucket (mini/state.json).
Uso (OpenAI):  base_url = https://<este-space>/mini/v1   model = "l4" | "t4" | "l4:<repo HF>" | "t4:<repo HF>"
Auth: X-API-Key o Bearer con una clave del Router (RIU_AGENT_API_KEYS / _2). La primera llamada enciende y responde 503 +
Retry-After mientras el modelo carga; las siguientes ya responden.
"""
from __future__ import annotations

import json
import hmac
import hashlib
import os
import threading
import time
from typing import Any

import httpx
from starlette.applications import Starlette
from starlette.requests import Request
from starlette.responses import JSONResponse, Response
from starlette.routing import Route

from door import _api, _token, bread, bwrite

PRICES = {"t4": ("t4-small", 0.40), "l4": ("l4x1", 0.80)}
DEFAULT_MODELS = {"t4": "Qwen/Qwen2.5-3B-Instruct", "l4": "Qwen/Qwen2.5-7B-Instruct"}
STATE = os.getenv("RIU_RESPALDO_ROOT", "router-respaldo").strip("/") + "/state.json"  # raiz propia del respaldo
LOCK = threading.Lock()


def _keys() -> set[str]:
    out: set[str] = set()
    for var in ("RIU_AGENT_API_KEYS", "RIU_AGENT_API_KEYS_2"):
        try:
            out |= set(json.loads(os.getenv(var) or "{}"))
        except ValueError:
            pass
    return out


_TOK = {"t": 0.0, "data": {}}


def _tokens() -> dict:
    """Tokens de conexion universal (banco del Router, solo huellas). Se releen cada 60 s."""
    if time.time() - _TOK["t"] > 60:
        try:
            root = os.getenv("RIU_ROOT", "router-inteligente-universal").strip("/")
            _TOK["data"] = (bread(f"{root}/banco/tokens.json") or {}).get("tokens") or {}
        except Exception:  # noqa: BLE001
            pass
        _TOK["t"] = time.time()
    return _TOK["data"]


def _authorized(req: Request) -> bool:
    """Clave maestra del Router, o token de agente activo con permiso "computo" (la GPU cuesta)."""
    auth = req.headers.get("authorization", "")
    key = req.headers.get("x-api-key") or (auth[7:].strip() if auth.lower().startswith("bearer ") else "")
    if not key:
        return False
    if key in _keys():
        return True
    rec = _tokens().get(hashlib.sha256(key.encode()).hexdigest()) if key.startswith("riu_") else None
    return bool(rec and rec.get("activo", True) and "computo" in (rec.get("permisos") or []))


def _director(req: Request) -> bool:
    """Clave del Director (X-Director-Key) contra su huella PBKDF2 (RIU_DIRECTOR_KEY_HASH). Nunca se guarda la clave."""
    cand, ref = req.headers.get("x-director-key") or "", os.getenv("RIU_DIRECTOR_KEY_HASH", "")
    if not cand or not ref.startswith("pbkdf2_sha256$"):
        return False
    _, iters, salt, expected = ref.split("$")
    got = hashlib.pbkdf2_hmac("sha256", cand.encode(), bytes.fromhex(salt), int(iters)).hex()
    return hmac.compare_digest(got, expected)


def _default(gpu: str) -> dict[str, Any]:
    return {"gpu": gpu, "flavor": PRICES[gpu][0], "price_h": PRICES[gpu][1], "model": DEFAULT_MODELS[gpu], "cap_usd": 5.0,
            "spent_usd": 0.0, "max_minutes": 120, "idle_s": 300, "blocked": False, "job_id": None, "url": None,
            "started": None, "last_call": None, "last_bill": None}


class Mini:
    def __init__(self) -> None:
        saved = bread(STATE) or {}
        self.s: dict[str, dict[str, Any]] = {g: {**_default(g), **saved.get(g, {})} for g in PRICES}
        threading.Thread(target=self._loop, name="mini-reaper", daemon=True).start()

    def save(self) -> None:
        try:
            bwrite(STATE, self.s)
        except Exception:  # noqa: BLE001
            pass

    def _bill(self, g: str) -> None:
        st, now = self.s[g], time.time()
        if st["job_id"] and st["last_bill"]:
            st["spent_usd"] = round(st["spent_usd"] + st["price_h"] * (now - st["last_bill"]) / 3600, 4)
        st["last_bill"] = now if st["job_id"] else None

    def stop(self, g: str, reason: str) -> None:
        st = self.s[g]
        self._bill(g)  # cobra hasta el ultimo segundo antes de apagar (el tope de 5 USD se respeta exacto)
        if st["job_id"]:
            try:
                _api().cancel_job(job_id=st["job_id"], namespace="COMAND-CENTER-1")
            except Exception:  # noqa: BLE001
                pass
        st.update(job_id=None, url=None, started=None, last_bill=None, stop_reason=reason)
        self.save()

    def ensure(self, g: str, model: str | None) -> dict[str, Any]:
        with LOCK:
            st = self.s[g]
            st["last_call"] = time.time()
            if st["blocked"]:
                return {"ready": False, "status": "NEEDS_APPROVAL", "spent_usd": st["spent_usd"], "cap_usd": st["cap_usd"]}
            if model and model != st["model"] and st["job_id"]:
                self.stop(g, "cambio de modelo")
            if model:
                st["model"] = model
            if not st["job_id"]:
                job = _api().run_job(image="vllm/vllm-openai:latest", flavor=st["flavor"], timeout=f"{int(st['max_minutes'])}m",
                                     command=["vllm", "serve", st["model"], "--port", "8000", "--dtype", "half", "--max-model-len", "8192"],
                                     expose=[8000], secrets={"HF_TOKEN": _token()}, namespace="COMAND-CENTER-1")
                st.update(job_id=job.id, url=f"https://{job.id}--8000.hf.jobs", started=time.time(), last_bill=time.time())
                self.save()
                return {"ready": False, "status": "STARTING", "job_id": job.id}
            try:
                ok = httpx.get(st["url"] + "/v1/models", headers={"Authorization": "Bearer " + _token()}, timeout=10).status_code == 200
            except Exception:  # noqa: BLE001
                ok = False
            return {"ready": ok, "status": "READY" if ok else "LOADING", "job_id": st["job_id"], "url": st["url"]}

    def _loop(self) -> None:
        while True:
            time.sleep(30)
            with LOCK:
                for g, st in self.s.items():
                    if not st["job_id"]:
                        continue
                    self._bill(g)
                    try:
                        stage = str(getattr(_api().inspect_job(job_id=st["job_id"], namespace="COMAND-CENTER-1").status, "stage", "")).upper()
                    except Exception:  # noqa: BLE001
                        stage = "UNKNOWN"
                    if any(x in stage for x in ("ERROR", "CANCELED", "COMPLETED", "DELETED")):
                        st.update(job_id=None, url=None, started=None, last_bill=None, stop_reason=stage)
                    elif st["spent_usd"] >= st["cap_usd"]:
                        st["blocked"] = True
                        self.stop(g, "tope de gasto alcanzado: requiere aprobacion")
                    elif st["last_call"] and time.time() - st["last_call"] >= st["idle_s"]:
                        self.stop(g, "5 min sin llamadas: dormido")
                self.save()


MINI: Mini | None = None


def _mini() -> Mini:
    global MINI
    if MINI is None:
        MINI = Mini()
    return MINI


def _split(model: str) -> tuple[str | None, str | None]:
    gpu, _, repo = model.partition(":")
    return (gpu, repo or None) if gpu in PRICES else (None, None)


async def status(req: Request) -> Response:
    if not _authorized(req):
        return JSONResponse({"detail": "RIU_API_KEY_REQUIRED"}, status_code=401)
    return JSONResponse({"gpus": _mini().s, "precios_usd_h": {g: p for g, (_, p) in PRICES.items()}})


async def config(req: Request) -> Response:
    if not _director(req):  # candado: costo, tiempo y aprobacion de gasto solo con la clave del Director
        return JSONResponse({"detail": "CLAVE_DIRECTOR_REQUERIDA (cabecera X-Director-Key)"}, status_code=403)
    if not _authorized(req):
        return JSONResponse({"detail": "RIU_API_KEY_REQUIRED"}, status_code=401)
    body = await req.json()
    g = body.get("gpu")
    if g not in PRICES:
        return JSONResponse({"detail": "gpu debe ser t4 o l4"}, status_code=400)
    st = _mini().s[g]
    for k, cast, lo, hi in (("cap_usd", float, 0.5, 5.0), ("max_minutes", int, 10, 600), ("idle_s", int, 60, 3600)):
        if k in body:
            st[k] = max(lo, min(hi, cast(body[k])))  # el tope por procesador nunca pasa de $5 sin aprobacion
    if body.get("model"):
        st["model"] = str(body["model"])[:200]
    _mini().save()
    return JSONResponse({"gpu": g, "config": st})


async def approve(req: Request) -> Response:
    if not _director(req):  # candado: costo, tiempo y aprobacion de gasto solo con la clave del Director
        return JSONResponse({"detail": "CLAVE_DIRECTOR_REQUERIDA (cabecera X-Director-Key)"}, status_code=403)
    """Trigger de aprobacion (boton de la UI): desbloquea y abre una nueva ventana de gasto de hasta cap_usd."""
    if not _authorized(req):
        return JSONResponse({"detail": "RIU_API_KEY_REQUIRED"}, status_code=401)
    body = await req.json()
    g = body.get("gpu")
    if g not in PRICES:
        return JSONResponse({"detail": "gpu debe ser t4 o l4"}, status_code=400)
    st = _mini().s[g]
    st.update(blocked=False, spent_usd=0.0, approved_at=time.time())
    _mini().save()
    return JSONResponse({"gpu": g, "status": "APROBADO", "cap_usd": st["cap_usd"]})


async def stop(req: Request) -> Response:
    if not _authorized(req):
        return JSONResponse({"detail": "RIU_API_KEY_REQUIRED"}, status_code=401)
    g = (await req.json()).get("gpu")
    if g not in PRICES:
        return JSONResponse({"detail": "gpu debe ser t4 o l4"}, status_code=400)
    with LOCK:
        _mini().stop(g, "apagado manual")
    return JSONResponse({"gpu": g, "status": "APAGADO"})


async def models(req: Request) -> Response:
    if not _authorized(req):
        return JSONResponse({"detail": "RIU_API_KEY_REQUIRED"}, status_code=401)
    return JSONResponse({"object": "list", "data": [{"id": g, "object": "model", "owned_by": "mini-router", "served": st["model"]}
                                                    for g, st in _mini().s.items()]})


async def chat(req: Request) -> Response:
    if not _authorized(req):
        return JSONResponse({"detail": "RIU_API_KEY_REQUIRED"}, status_code=401)
    body = await req.json()
    g, repo = _split(str(body.get("model") or ""))
    if g is None:
        return JSONResponse({"detail": "model debe ser t4, l4, t4:<repo> o l4:<repo>"}, status_code=400)
    st = _mini().ensure(g, repo)
    if not st["ready"]:
        code = 402 if st["status"] == "NEEDS_APPROVAL" else 503
        return JSONResponse(st, status_code=code, headers={"Retry-After": "60"})
    body["model"] = _mini().s[g]["model"]
    body["stream"] = False
    async with httpx.AsyncClient(timeout=300) as c:
        r = await c.post(_mini().s[g]["url"] + "/v1/chat/completions", json=body, headers={"Authorization": "Bearer " + _token()})
    return Response(r.content, status_code=r.status_code, media_type="application/json")


app = Starlette(routes=[
    Route("/mini/status", status), Route("/mini/config", config, methods=["POST"]), Route("/mini/approve", approve, methods=["POST"]),
    Route("/mini/stop", stop, methods=["POST"]), Route("/mini/v1/models", models), Route("/mini/v1/chat/completions", chat, methods=["POST"]),
])

