async def github_api(method: Literal["GET", "POST", "PUT", "PATCH", "DELETE"], path: str, body: dict[str, Any] | None = None, params: dict[str, Any] | None = None) -> Any:
    """Call an arbitrary api.github.com REST path with the dedicated PAT."""
